SELECT store_id, product_sku, available_today_quantity
FROM store_inventory
WHERE store_id='store_innsbruck_wilten' AND product_sku IN ('MAC-20MBP5AC');

SELECT sku, path, brand, series, model, name FROM products WHERE brand='Engelbert Strauss' AND series LIKE '%Engelbert Strauss Classic%' AND model='e.s. 37H-N9K' AND name='Work Trousers' AND json_extract(properties,'$.color_family')='Gray' LIMIT 5;
SELECT sku, path, brand, series, model, name FROM products WHERE brand='Bondex' AND series LIKE '%Bondex Garden Classic%' AND model='106-TS1' AND name='Wood Stain and Deck Oil' AND json_extract(properties,'$.product_type')='lacquer' LIMIT 5;
SELECT sku, path, brand, series, model, name FROM products WHERE brand='3M' AND series LIKE '%Ventilated SecureFit%' AND model='2CE-B35' AND name='Safety Eyewear' AND json_extract(properties,'$.lens_color')='Clear' AND json_extract(properties,'$.size')='XL' LIMIT 5;
